-- To do "Verificér første rigtige tilbagekaldelse gennem recalls-sync": statuskommentar. Kun skrivning til to do-listen.
insert into public.admin_todo_comments (todo_id, body)
select id,
 'Jan har overtaget opgaven (14. okt. 2026, Claude, skrivebeskyttet tjek). Første rigtige tilbagekaldelse er kommet: "Metalstykker i tuber med Makrelkræs" (Fødevarestyrelsen, udgivet 12. okt. kl. 14.02 dansk tid, hentet kl. 19.00 dansk tid). (1) Gemt rigtigt: status ready, to gyldige stregkoder (karton 15705550826125 og stk. 5705550826128), kilde-link og tekst på plads. (2) Match: styk-stregkoden findes i produkter (Amanda, "Makrel i tomat smørbar"); navnet afviger fra "Makrelkræs", men stregkoden er den rigtige. (3) Hændelsen recall_published er behandlet (status done, 1 forsøg, ingen fejl). (4) Besked til brugere: 0 sendt, og det er rigtigt, fordi ingen brugere har produktet som favorit, på indkøbslisten eller scannet det de sidste 90 dage. Dermed er selve afsendelsen til rigtige brugere endnu ikke set på rigtige data. Forslag (afventer Jans ja): Jan lægger Amanda-produktet 5705550826128 som favorit på sin egen konto og vi udløser beskeden igen kun til Jan, så push og besked ses ende til ende. Står åben til fristen 16. okt.'
from public.admin_todos where title = '[Før beta] Verificér første rigtige tilbagekaldelse gennem recalls-sync';
